#!/usr/bin/env python3
"""
Packaged launcher for the exact V3-validated price-agnostic scalp shadow.
Signal-only research. NO ORDERS.

The embedded implementation is gzip+base64 packaged only to preserve the exact
clean-room-tested bytes in one immutable deployment file. Its SHA-256 is checked
before execution.
"""
import base64,gzip,hashlib

EXPECTED_SHA256='3fdb2ef60f184e1ce2cef306c1db2a9de03b3e7b1a27c32b6bfffabb2cf60c48'
PAYLOAD=(
''
''
''
)
raw=gzip.decompress(base64.b64decode(PAYLOAD))
actual=hashlib.sha256(raw).hexdigest()
if actual != EXPECTED_SHA256:
    raise SystemExit(f'BOOTSTRAP INTEGRITY FAIL | expected {EXPECTED_SHA256} got {actual}')
print(f'SCALP MOVE BOOTSTRAP V1 | SHA256 {actual} | SIGNAL ONLY | NO ORDERS',flush=True)
exec(compile(raw.decode('utf-8'),'scalp_move_shadow_v1_impl.py','exec'),globals())
